class Solution {
public:
    bool findSubarrays(vector<int>& nums) {
        unordered_set<long long> seen;
        for (int i = 0; i + 1 < (int)nums.size(); i++) {
            long long sum = (long long)nums[i] + nums[i + 1];
            if (seen.count(sum)) return true;
            seen.insert(sum);
        }
        return false;
    }
};
